import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`window-door-estimate`,heroTitle:`Generate window & door estimates in minutes`,heroSubtitle:`Perplexity Computer analyzes your uploaded plans and measurements, sizes units and labor, and drafts a detailed window and door estimate automatically.`,hasInputUrl:!1,hasInputFile:!0,inputFileCta:`Upload your window and door plans`,inputFileAccept:`.pdf,.doc,.docx,.csv,.xlsx,.xls,.png,.jpg,.jpeg`,inputFilePrefill:`I've uploaded plans, measurements, schedules, or site photos for a window and door job. Build a complete window and door estimate. (1) Extract opening counts, dimensions, unit types, glazing needs, hardware, trim requirements, demolition scope, and installation constraints from the uploaded files. (2) Estimate materials, labor, disposal, specialty equipment, and finishing work. (3) Build pricing options with assumptions, alternates, and margin. (4) Highlight exclusions, field-verification items, and lead-time questions that should be confirmed before sending. (5) Deliver a detailed window and door estimate with line-item pricing, scope summary, and next steps that is ready for the customer.`,heroOverlaySteps:[`Extracting opening sizes, unit types, glazing needs, and install constraints from your files`,`Sizing materials, labor, disposal, and finishing work`,`Building pricing options with assumptions, alternates, and margin`,`Customer-ready window and door estimate with scope summary, ready to send`],generatingSteps:[`Reading the uploaded plans, measurements, schedules, and site photos`,`Designing an agent to organize product selections and labor assumptions`,`Configuring estimate logic for alternates, exclusions, and margin`,`Preparing a detailed window and door estimate with line items and next steps`],featureSectionTitle:`From plans to install-ready estimate`,featureCardTitles:[`Connects to your estimating workflow`,`Estimates built around product and install details`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Docs, photos, schedules, and internal planning workflows stay connected so review and revisions move faster.`,`Unit counts. Hardware details. Labor assumptions. Alternates. Computer gives your team a window and door estimate draft that is ready for customer review.`],capabilitySectionTitle:`Your estimator, on autopilot`,capabilitySectionSubtitle:`Upload the scope, get back a window and door estimate built around the real openings and install conditions.`,capabilityCards:[{title:`Scope Extraction`,description:`Computer can extract opening sizes, unit types, glazing needs, hardware details, and installation constraints from measurements and job notes.`},{title:`Materials & Labor Planning`,description:`Computer can size units, trim, disposal, specialty equipment, and labor hours so the estimate reflects the actual installation scope.`},{title:`Pricing Options`,description:`Computer can build pricing with assumptions, alternates, and margin so your team can present options clearly and close faster.`},{title:`Connect Your Tools`,description:`Computer can organize estimate drafts across docs, sheets, and internal workflows so review and handoff are easy for your team.`},{title:`Knows Your Standards`,description:`Computer can remember your preferred manufacturers, markup rules, and estimate structure across sessions so every quote stays consistent.`},{title:`Revision Support`,description:`Computer can update the estimate when dimensions, product specs, or finishing requirements change after the first draft.`}]});export{t as default};
